/* @autogenerated */
package net.civeira.phylax.feature.observe.store;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class JsonlTelemetryStoreLimitsUnitTest {

  @TempDir
  Path root;

  private static List<ObsLog> logs(final int count, final int bytes) {
    long now = System.currentTimeMillis();
    String text = "x".repeat(bytes);
    List<ObsLog> result = new ArrayList<>();
    for (int i = 0; i < count; i++) {
      result.add(
          new ObsLog(now, "api", "INFO", "test", text + i, null, null, null, null, null, null));
    }
    return result;
  }

  private Path today() {
    return root.resolve(LocalDate.now(ZoneOffset.UTC).toString());
  }

  private List<String> files() throws IOException {
    try (var files = Files.list(today())) {
      return files.map(file -> file.getFileName().toString()).sorted().toList();
    }
  }

  private static TelemetryQuery all() {
    return TelemetryQuery.builder().from(0).to(Long.MAX_VALUE / 2).minLevel(Optional.empty())
        .text(Optional.empty()).limit(10_000).build();
  }

  @Test
  @DisplayName("A day is cut in segments of segment-mb and the queries read all of them")
  void segments() throws IOException {
    JsonlTelemetryStore store = new JsonlTelemetryStore(root.toString());
    store.segmentMb = 1;
    store.appendLogs(logs(300, 10_000));
    Assertions.assertEquals(List.of("logs.1.jsonl", "logs.2.jsonl", "logs.jsonl"), files());
    Assertions.assertEquals(300, store.logs(all()).size());
    // A new instance (a restart) goes on with the last segment
    JsonlTelemetryStore restarted = new JsonlTelemetryStore(root.toString());
    restarted.segmentMb = 1;
    restarted.appendLogs(logs(1, 10));
    Assertions.assertEquals(3, files().size());
    Assertions.assertEquals(301, restarted.logs(all()).size());
  }

  @Test
  @DisplayName("Above the limit the oldest segments of today go, never the one being written")
  void reclaimToday() throws IOException {
    JsonlTelemetryStore store = new JsonlTelemetryStore(root.toString());
    store.segmentMb = 1;
    store.appendLogs(logs(300, 10_000));
    store.enforce(new RetentionPolicy(14, 7, 2, 15, 400));
    Assertions.assertEquals(List.of("logs.2.jsonl"), files());
    Assertions.assertFalse(store.full());
    store.appendLogs(logs(1, 10));
    Assertions.assertEquals(0, store.rejected());
  }

  @Test
  @DisplayName("When nothing else can be deleted the store is full and rejects the new events")
  void hardLimit() throws IOException {
    JsonlTelemetryStore store = new JsonlTelemetryStore(root.toString());
    store.appendLogs(logs(150, 10_000));
    store.enforce(new RetentionPolicy(14, 7, 1, 15, 400));
    Assertions.assertTrue(store.full());
    long size = Files.size(today().resolve("logs.jsonl"));
    store.appendLogs(logs(5, 10));
    Assertions.assertEquals(5, store.rejected());
    Assertions.assertEquals(size, Files.size(today().resolve("logs.jsonl")));
    // A larger limit lets it write again
    store.enforce(new RetentionPolicy(14, 7, 10, 15, 400));
    Assertions.assertFalse(store.full());
    store.appendLogs(logs(1, 10));
    Assertions.assertEquals(5, store.rejected());
  }

  @Test
  @DisplayName("The disk limit deletes logs and spans before the metrics, and never the hourly rollup")
  void limitKeepsAggregates() throws IOException {
    Path old = root.resolve(LocalDate.now(ZoneOffset.UTC).minusDays(3).toString());
    Files.createDirectories(old);
    Files.write(old.resolve("logs.jsonl"), new byte[700_000]);
    Files.write(old.resolve("metrics.jsonl"), new byte[200_000]);
    Files.write(old.resolve("metrics-1h.jsonl"), new byte[10_000]);
    JsonlTelemetryStore store = new JsonlTelemetryStore(root.toString());
    store.appendLogs(logs(60, 10_000));
    store.enforce(new RetentionPolicy(90, 90, 1, 90, 400));
    Assertions.assertFalse(Files.exists(old.resolve("logs.jsonl")));
    Assertions.assertTrue(Files.exists(old.resolve("metrics.jsonl")));
    Assertions.assertTrue(Files.exists(old.resolve("metrics-1h.jsonl")));
  }

  @Test
  @DisplayName("The retention by level never deletes the metric points")
  void levelsKeepMetrics() throws IOException {
    long old = System.currentTimeMillis() - 100 * 3_600_000L;
    JsonlTelemetryStore store = new JsonlTelemetryStore(root.toString());
    store.appendPoints(List.of(new net.civeira.phylax.feature.observe.metric.MetricPoint(
        old / 60_000 * 60_000, 60_000, "api", "/x", "GET", 3, 1, 30, new long[0])));
    store.appendLogs(
        List.of(new ObsLog(old, "api", "INFO", "t", "old", null, null, null, null, null, null)));
    store.purgeLevels(new RetentionPolicy(14, 7, 0, 15, 400)
        .withLevels(new RetentionPolicy.LevelRetention(2, 12, 24, 48)));
    Assertions.assertTrue(store.logs(all()).isEmpty());
    Assertions.assertEquals(1,
        store.points(0, Long.MAX_VALUE / 2, 60_000, java.util.Set.of()).size());
  }
}
